import itertools

def calculate_V(x, y, z, a, b, c):
    """Calculates the value V for a given triplet (x, y, z) and query (a, b, c)."""
    term1 = abs(x + y - a - b)
    term2 = abs(y + z - b - c)
    term3 = abs(z + x - c - a)
    return term1 + term2 + term3

# Proposed Queries
queries = [
    (5, 5, 5),  # Q1: Uniform mid-range
    (0, 9, 0),  # Q2: Asymmetric boundary
    (3, 0, 6)   # Q3: Medium asymmetry
]

# Store results: mapping of outcome triplet to list of (x, y, z) that produced it
outcome_map = {}
total_states = 1000

# Iterate over all 1000 possible secret triplets (x, y, z)
for x in range(10):
    for y in range(10):
        for z in range(10):
            state = (x, y, z)

            # Calculate the outcomes for the 3 queries
            outcomes = []
            for a, b, c in queries:
                v = calculate_V(x, y, z, a, b, c)
                outcomes.append(v)

            outcome_tuple = tuple(outcomes)

            if outcome_tuple not in outcome_map:
                outcome_map[outcome_tuple] = []

            outcome_map[outcome_tuple].append(state)

# Check for collisions
collisions = {outcome: len(states) for outcome, states in outcome_map.items() if len(states) > 1}

print("--- Simulation Results ---")
print(f"Total unique outcome tuples found: {len(outcome_map)}")
print(f"Number of collision points (tuples mapped to >1 state): {len(collisions)}")

if collisions:
    print("\nSample collision groups (Outcome Tuple -> Number of States):")
    # Print a few samples of collisions
    sample_count = 0
    for outcome, count in collisions.items():
        if sample_count < 3:
            print(f"Outcome {outcome}: {count} states collide.")
            sample_count += 1
        else:
            break
else:
    print("\nSuccess: No collisions found among the tested states.")

# Check if all 1000 states are mapped
if len(outcome_map) == total_states:
    print("\nAll 1000 states are uniquely mapped (no collisions).")
else:
    print(f"\nWarning: Only {len(outcome_map)} unique outcomes found out of 1000 states.")
